import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import TaskCreationPage from "./pages/TaskCreationPage";
import ApproverActionPage from "./pages/ApproverActionPage";

function App() {
  return (
    <Router>
      <div className="min-h-screen bg-gray-100">
        <nav className="bg-white shadow p-4 mb-6">
          <div className="container mx-auto flex space-x-4">
            <Link to="/" className="text-blue-600 font-semibold hover:underline">Task Creation</Link>
            <Link to="/approver" className="text-blue-600 font-semibold hover:underline">Approver Action</Link>
          </div>
        </nav>
        <main className="container mx-auto px-4">
        <Routes>
          <Route path="/" element={<TaskCreationPage />} />
            <Route path="/approver" element={<ApproverActionPage />} />
        </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App; // ✅ REQUIRED for index.js to work
